<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { AlertTriangle,ChartNoAxesCombined,Clock3,Coins,RefreshCw,Search,X } from '@lucide/vue'
import { getAdminDashboardSnapshot } from '@/api/admin/dashboard'
import { getAdminUsageError,getAdminUsageStats,listAdminUsage,listAdminUsageErrors } from '@/api/admin/usage'
import type { AdminDashboardSnapshot,AdminUsageError,AdminUsageLog,AdminUsageStats } from '@/api/admin/types'
import TrendChart from '@/components/TrendChart.vue'
import { formatCost,formatCount,formatDateTime,formatDuration } from '@/lib/format'

type RangeDays=1|7|30;const rangeDays=ref<RangeDays>(7);const userFilter=ref('');const modelFilter=ref('');const activeTab=ref<'records'|'errors'>('records');const stats=ref<AdminUsageStats|null>(null);const snapshot=ref<AdminDashboardSnapshot|null>(null);const records=ref<AdminUsageLog[]>([]);const recordTotal=ref(0);const errors=ref<AdminUsageError[]>([]);const errorTotal=ref(0);const selectedError=ref<AdminUsageError|null>(null);const loading=ref(true);const refreshing=ref(false);const issues=ref<string[]>([])
function range(){const end=new Date(),start=new Date(end);start.setDate(start.getDate()-rangeDays.value+1);return{start_date:start.toISOString().slice(0,10),end_date:end.toISOString().slice(0,10)}}const filters=computed(()=>({...range(),...(Number(userFilter.value)>0?{user_id:Number(userFilter.value)}:{}),...(modelFilter.value.trim()?{model:modelFilter.value.trim()}: {})}));const fullError=computed(()=>!loading.value&&!stats.value&&!snapshot.value&&!records.value.length&&issues.value.includes('汇总')&&issues.value.includes('趋势')&&issues.value.includes('明细'))
async function load(background=false){if(background)refreshing.value=true;else loading.value=true;issues.value=[];const [s,snap,list]=await Promise.allSettled([getAdminUsageStats(filters.value),getAdminDashboardSnapshot({...filters.value,granularity:rangeDays.value===1?'hour':'day'}),listAdminUsage({...filters.value,page:1,page_size:20})]);if(s.status==='fulfilled')stats.value=s.value;else issues.value.push('汇总');if(snap.status==='fulfilled')snapshot.value=snap.value;else issues.value.push('趋势');if(list.status==='fulfilled'){records.value=list.value.items;recordTotal.value=list.value.total}else issues.value.push('明细');loading.value=false;refreshing.value=false}
async function loadErrors(){const f=filters.value;const start_time=new Date(`${f.start_date}T00:00:00`).toISOString(),end_time=new Date(`${f.end_date}T23:59:59.999`).toISOString();try{const res=await listAdminUsageErrors({page:1,page_size:20,view:'all',start_time,end_time,...(f.user_id?{user_id:f.user_id}:{}),...(f.model?{model:f.model}:{})});errors.value=res.items;errorTotal.value=res.total}catch{issues.value.push('错误请求')}}
function apply(){void load(true);if(activeTab.value==='errors')void loadErrors()}function selectTab(tab:'records'|'errors'){activeTab.value=tab;if(tab==='errors')void loadErrors()}async function openError(row:AdminUsageError){selectedError.value=row;try{selectedError.value=await getAdminUsageError(row.id)}catch{}}
onMounted(()=>void load())
</script>
<template><div class="usage-page"><header class="page-header drag-region"><div><span>GLOBAL USAGE</span><h1>全站用量</h1><p>追踪用户、账号与模型的调用明细和错误请求。</p></div><div class="header-tools no-drag"><div class="range"><button v-for="days in [1,7,30] as RangeDays[]" :key="days" :aria-pressed="rangeDays===days" @click="rangeDays=days;apply()">{{ days===1?'24小时':`${days}天` }}</button></div><button class="icon" :disabled="refreshing" @click="load(true)"><RefreshCw :size="16" :class="{spinning:refreshing}" /></button></div></header>
<p v-if="issues.length" class="warning"><AlertTriangle :size="15" />部分数据未更新：{{ issues.join('、') }}</p><section v-if="fullError" class="usage-error-state" data-testid="usage-error-state"><strong>全站用量加载失败</strong><span>当前无法取得管理端用量数据，请检查网络后重试。</span><button type="button" data-testid="retry-usage" @click="load()">重新加载</button></section><section class="metrics"><div data-testid="usage-requests"><ChartNoAxesCombined :size="18" /><span>请求数</span><strong>{{ formatCount(stats?.total_requests) }}</strong></div><div><Coins :size="18" /><span>用户消费</span><strong>{{ formatCost(stats?.total_actual_cost) }}</strong></div><div><Coins :size="18" /><span>账号成本</span><strong>{{ formatCost(stats?.total_account_cost) }}</strong></div><div><Clock3 :size="18" /><span>平均耗时</span><strong>{{ formatDuration(stats?.average_duration_ms) }}</strong></div></section>
<section class="trend"><header><div><h2>调用趋势</h2><p>全站请求与 Token 变化</p></div><span>{{ snapshot?.start_date }} 至 {{ snapshot?.end_date }}</span></header><TrendChart :points="snapshot?.trend??[]" /></section>
<form class="filters" data-testid="usage-filters" @submit.prevent="apply"><label><Search :size="15" /><input v-model="userFilter" data-testid="usage-user-filter" inputmode="numeric" placeholder="用户 ID" /></label><label><Search :size="15" /><input v-model="modelFilter" placeholder="模型名称" /></label><button type="submit">应用筛选</button></form>
<section class="details"><nav><button :aria-pressed="activeTab==='records'" @click="selectTab('records')">用量明细 <span>{{ recordTotal }}</span></button><button data-testid="usage-errors-tab" :aria-pressed="activeTab==='errors'" @click="selectTab('errors')">错误请求 <span>{{ errorTotal }}</span></button></nav><div v-if="loading" class="loading"><i v-for="n in 6" :key="n" /></div><div v-else-if="activeTab==='records'&&!records.length" class="detail-empty" data-testid="usage-records-empty"><strong>暂无用量明细</strong><span>所选条件下还没有请求记录。</span></div><div v-else-if="activeTab==='records'" class="table records"><div class="row head"><span>用户</span><span>账号 / Key</span><span>模型</span><span>Token</span><span>消费</span><span>耗时</span><span>时间</span></div><div v-for="row in records" :key="row.id" class="row"><div><strong>{{ row.user?.email||`#${row.user_id??'-'}` }}</strong></div><div><strong>{{ row.account?.name||'—' }}</strong><span>{{ row.api_key?.name||'—' }}</span></div><strong>{{ row.model }}</strong><span>{{ formatCount((row.input_tokens??0)+(row.output_tokens??0)+(row.cache_read_tokens??0)+(row.cache_creation_tokens??0)) }}</span><span>{{ formatCost(row.actual_cost) }}</span><span>{{ formatDuration(row.duration_ms) }}</span><span>{{ formatDateTime(row.created_at) }}</span></div></div><div v-else-if="!errors.length" class="detail-empty" data-testid="usage-errors-empty"><strong>暂无错误请求</strong><span>所选条件下没有记录到失败请求。</span></div><div v-else class="table errors"><div class="row head"><span>用户</span><span>账号</span><span>模型</span><span>状态</span><span>错误</span><span>时间</span></div><button v-for="row in errors" :key="row.id" class="row" :data-testid="`usage-error-${row.id}`" @click="openError(row)"><span>{{ row.user_email }}</span><span>{{ row.account_name||'—' }}</span><strong>{{ row.model }}</strong><em>{{ row.status_code }}</em><span>{{ row.message }}</span><span>{{ formatDateTime(row.created_at) }}</span></button></div></section>
<Transition name="drawer"><div v-if="selectedError" class="drawer-backdrop" @mousedown.self="selectedError=null"><aside data-testid="usage-error-detail"><header><div><h2>错误请求 #{{ selectedError.id }}</h2><p>{{ selectedError.platform }} · {{ selectedError.model }}</p></div><button @click="selectedError=null"><X :size="18" /></button></header><div class="error-hero"><strong>{{ selectedError.status_code }}</strong><span>{{ selectedError.message }}</span></div><dl><div><dt>用户</dt><dd>{{ selectedError.user_email }}</dd></div><div><dt>账号</dt><dd>{{ selectedError.account_name||'—' }}</dd></div><div><dt>分组</dt><dd>{{ selectedError.group_name||'—' }}</dd></div><div><dt>请求 ID</dt><dd>{{ selectedError.request_id||'—' }}</dd></div></dl><section v-if="selectedError.error_body"><h3>错误正文</h3><pre>{{ selectedError.error_body }}</pre></section><section v-if="selectedError.upstream_error_message"><h3>上游信息</h3><pre>{{ selectedError.upstream_error_message }}</pre></section></aside></div></Transition>
</div></template>
<style scoped>
.usage-page{width:100%;min-height:100%;padding:28px 30px 34px;overflow:auto}.page-header{display:flex;align-items:flex-end;justify-content:space-between;gap:20px}.page-header>div>span{display:block;margin-bottom:5px;color:var(--accent);font-size:11px;font-weight:720;letter-spacing:.08em}.page-header h1{margin:0;font-size:25px}.page-header p{margin:7px 0 0;color:var(--text-secondary);font-size:14px}.header-tools,.range{display:flex;gap:8px}.range{height:34px;padding:3px;background:#e9eef5;border-radius:7px}.range button{padding:0 10px;border:0;border-radius:5px;background:transparent;color:var(--text-secondary);font-size:12px}.range button[aria-pressed=true]{background:white;color:var(--accent);box-shadow:0 2px 7px rgba(40,58,85,.1)}.icon{display:grid;width:34px;border:1px solid var(--border-subtle);border-radius:7px;background:white;color:var(--text-secondary);place-items:center}.warning{display:flex;align-items:center;gap:7px;padding:9px 11px;background:#fff8e8;border:1px solid #f0dda9;border-radius:7px;color:#8a641b;font-size:12px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);margin-top:20px;overflow:hidden;background:rgba(255,255,255,.76);border:1px solid var(--border-subtle);border-radius:8px}.metrics>div{display:grid;min-height:70px;grid-template-columns:24px 1fr auto;align-items:center;gap:7px;padding:0 17px;border-right:1px solid var(--border-subtle)}.metrics>div:last-child{border-right:0}.metrics svg{color:var(--accent)}.metrics span{color:var(--text-secondary);font-size:12px}.metrics strong{font-family:var(--font-data);font-size:18px}.trend{display:flex;min-height:292px;flex-direction:column;margin-top:14px;padding:18px 20px 12px;background:rgba(255,255,255,.76);border:1px solid var(--border-subtle);border-radius:8px}.trend>header{display:flex;justify-content:space-between}.trend h2{margin:0;font-size:16px}.trend p{margin:3px 0 0;color:var(--text-tertiary);font-size:11px}.trend header>span{color:var(--text-tertiary);font-size:11px}.filters{display:flex;gap:8px;margin-top:14px}.filters label{display:flex;min-width:160px;height:37px;align-items:center;gap:7px;padding:0 10px;background:white;border:1px solid var(--border-subtle);border-radius:7px;color:var(--text-tertiary)}.filters input{min-width:0;border:0;outline:0;font:inherit;font-size:12px}.filters button{height:37px;padding:0 13px;border:0;border-radius:7px;background:var(--accent);color:white}.details{margin-top:12px;overflow:hidden;background:rgba(255,255,255,.8);border:1px solid var(--border-subtle);border-radius:8px}.details nav{display:flex;height:44px;align-items:end;padding:0 13px;border-bottom:1px solid var(--border-subtle)}.details nav button{height:43px;padding:0 12px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--text-secondary)}.details nav button[aria-pressed=true]{border-bottom-color:var(--accent);color:var(--accent);font-weight:650}.details nav span{margin-left:5px;color:var(--text-tertiary);font-size:10px}.table{min-width:830px}.row{display:grid;min-height:54px;align-items:center;gap:10px;padding:0 14px;border-bottom:1px solid var(--border-subtle);color:var(--text-secondary);font-size:10px}.records .row{grid-template-columns:1.2fr 1fr 1fr 70px 65px 58px 108px}.errors .row{grid-template-columns:1.1fr 1fr 1fr 52px 1.7fr 112px}.row.head{min-height:38px;background:#f6f8fb;color:var(--text-tertiary);font-weight:650}.row>div{display:grid;gap:2px}.row strong{overflow:hidden;color:var(--text-primary);font-size:11px;text-overflow:ellipsis;white-space:nowrap}.row em{width:max-content;padding:3px 6px;background:#fff0ed;border-radius:4px;color:#ad4939;font-style:normal}.errors button.row{width:100%;border-right:0;border-left:0;background:transparent;text-align:left;cursor:pointer}.loading{display:grid;gap:9px;padding:16px}.loading i{height:42px;background:#edf1f5;border-radius:6px}.drawer-backdrop{position:fixed;z-index:90;inset:0;background:rgba(31,42,58,.16);backdrop-filter:blur(5px)}aside{position:absolute;top:0;right:0;width:min(500px,58vw);min-width:420px;height:100%;padding:26px;overflow:auto;background:#fafcff;box-shadow:-18px 0 54px rgba(32,47,68,.16)}aside header{display:flex;justify-content:space-between}aside h2{margin:0;font-size:19px}aside header p{margin:3px 0 0;color:var(--text-tertiary);font-size:12px}aside header button{border:0;background:transparent;color:var(--text-tertiary)}.error-hero{display:grid;grid-template-columns:54px 1fr;align-items:center;gap:12px;margin-top:20px;padding:14px;background:#fff0ed;border:1px solid #efcbc4;border-radius:8px;color:#a84536}.error-hero strong{font-family:var(--font-data);font-size:20px}.error-hero span{font-size:12px}dl{margin-top:14px;background:white;border:1px solid var(--border-subtle);border-radius:8px}dl div{display:flex;min-height:40px;align-items:center;justify-content:space-between;padding:0 11px;border-bottom:1px solid var(--border-subtle)}dt{color:var(--text-tertiary);font-size:11px}dd{margin:0;font-family:var(--font-data);font-size:11px}aside section h3{margin:20px 0 8px;font-size:12px}pre{max-height:260px;padding:12px;overflow:auto;background:#f1f4f8;border-radius:7px;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}.spinning{animation:spin .75s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@container app-content (max-width:900px){.usage-page{padding:24px}.metrics{grid-template-columns:repeat(2,1fr)}.metrics>div:nth-child(2){border-right:0}.metrics>div:nth-child(-n+2){border-bottom:1px solid var(--border-subtle)}.details{overflow-x:auto}}@container app-content (max-width:700px){.page-header{align-items:flex-start;flex-direction:column}.filters{flex-wrap:wrap}.filters label{flex:1}.trend{min-height:260px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
.usage-error-state,.detail-empty{display:grid;align-content:center;justify-items:center;gap:7px;color:var(--text-tertiary)}.usage-error-state{min-height:150px;margin-top:14px;padding:20px;background:white;border:1px solid #efcbc4;border-radius:8px}.usage-error-state strong,.detail-empty strong{color:var(--text-primary);font-size:14px}.usage-error-state span,.detail-empty span{font-size:12px}.usage-error-state button{margin-top:5px;padding:7px 11px;border:0;border-radius:6px;background:var(--accent);color:white}.detail-empty{min-height:220px}
</style>
